// Covers pi session idle expiry and per-process admission limits without model calls.

import assert from "node:assert/strict";
import test from "node:test";

import { YinshiSidecar } from "../src/sidecar.js";

function fakeSession(record, name) {
  return {
    piSession: {
      dispose() {
        record.push(`dispose:${name}`);
      },
    },
    unsubscribe() {
      record.push(`unsubscribe:${name}`);
    },
    cancelRequested: false,
  };
}

test("idle pi sessions past the retention window are disposed and removed", () => {
  const sidecar = new YinshiSidecar();
  const record = [];
  sidecar.activeSessions.set("idle", {
    ...fakeSession(record, "idle"),
    lastActivityMs: 1,
  });
  sidecar.activeSessions.set("recent", {
    ...fakeSession(record, "recent"),
    lastActivityMs: 2_000_000,
  });

  sidecar._pruneIdlePiSessions(2_000_000);

  assert.equal(sidecar.activeSessions.has("idle"), false);
  assert.equal(sidecar.activeSessions.has("recent"), true);
  assert.deepEqual(record, ["unsubscribe:idle", "dispose:idle"]);
});

test("a pi session entry with no usable timestamp is removed", () => {
  const sidecar = new YinshiSidecar();
  const record = [];
  sidecar.activeSessions.set("broken", {
    ...fakeSession(record, "broken"),
    lastActivityMs: "not-a-number",
  });

  sidecar._pruneIdlePiSessions(1_000);

  assert.equal(sidecar.activeSessions.size, 0);
  assert.deepEqual(record, ["unsubscribe:broken", "dispose:broken"]);
});

test("pruning tolerates a pi session that throws while disposing", () => {
  const sidecar = new YinshiSidecar();
  sidecar.activeSessions.set("hostile", {
    lastActivityMs: 1,
    unsubscribe() {
      throw new Error("unsubscribe failed");
    },
    piSession: {
      dispose() {
        throw new Error("dispose failed");
      },
    },
  });

  sidecar._pruneIdlePiSessions(2_000_000);

  assert.equal(sidecar.activeSessions.size, 0);
});

test("admitting a new pi session evicts the least recently used one at the cap", () => {
  const sidecar = new YinshiSidecar();
  const record = [];
  const now = 5_000_000;
  for (let index = 0; index < 16; index += 1) {
    sidecar.activeSessions.set(`session-${index}`, {
      ...fakeSession(record, `session-${index}`),
      lastActivityMs: now - index,
    });
  }

  sidecar._makeRoomForPiSession(now);

  assert.equal(sidecar.activeSessions.size, 15);
  assert.equal(sidecar.activeSessions.has("session-15"), false);
  assert.equal(sidecar.activeSessions.has("session-0"), true);
  assert.deepEqual(record, ["unsubscribe:session-15", "dispose:session-15"]);
});

test("making room is a no-op while the process is below the cap", () => {
  const sidecar = new YinshiSidecar();
  const record = [];
  sidecar.activeSessions.set("only", {
    ...fakeSession(record, "only"),
    lastActivityMs: 10,
  });

  sidecar._makeRoomForPiSession(20);

  assert.equal(sidecar.activeSessions.size, 1);
  assert.deepEqual(record, []);
});

test("releasing a pi session disposes it and reports whether it existed", () => {
  const sidecar = new YinshiSidecar();
  const record = [];
  sidecar.activeSessions.set("live", {
    ...fakeSession(record, "live"),
    lastActivityMs: 10,
  });

  assert.equal(sidecar.releasePiSession("live"), true);
  assert.equal(sidecar.releasePiSession("live"), false);
  assert.equal(sidecar.activeSessions.size, 0);
  assert.deepEqual(record, ["unsubscribe:live", "dispose:live"]);
});

test("the pi session clock rejects values that are not safe timestamps", () => {
  const sidecar = new YinshiSidecar();

  assert.throws(() => sidecar._pruneIdlePiSessions(-1), TypeError);
  assert.throws(() => sidecar._pruneIdlePiSessions(1.5), TypeError);
});

