 * Remove emoji characters only. Whitespace is left exactly as it was, so this
 * doubles as the detection primitive.
 */
function removeEmojiCharacters(text: string): string {
	const sweptText = text.replace(EMOJI_REGEX, "");

	return [...sweptText]
		.filter((char) => {
			const code = char.codePointAt(0)!;
			// Check if character is in emoji ranges
			const isEmoji =
				(code >= 0x1f300 && code <= 0x1f9ff) ||
				(code >= 0x1fa00 && code <= 0x1ffff) ||
				(code >= 0x2600 && code <= 0x26ff) ||
				(code >= 0x2700 && code <= 0x27bf) ||
				(code >= 0x1f600 && code <= 0x1f64f) ||
				(code === 0x231a || code === 0x231b || code === 0x23f0 || code === 0x23f3 ||
					code === 0x25fd || code === 0x26fa || code === 0x270a || code === 0x270b ||
					code === 0x270c || code === 0x270d || code === 0x2728 || code === 0x2744 ||
					code === 0x2753 || code === 0x2754 || code === 0x2755 || code === 0x2757 ||
					code === 0x2b50 || code === 0x1f1e6);
			return !isEmoji;
		})
		.join("");
}

/**
 * True when the text carries at least one emoji.
 *
 * This must never consider whitespace. Indented source code and aligned
 * markdown tables are not emoji.
 */
function containsEmoji(text: string): boolean {
	return removeEmojiCharacters(text) !== text;
}

/**
 * Remove all emoji from a string.
 *
 * Runs of spaces are tidied only where an emoji was actually removed, because
 * that is the case where removal can leave a gap behind.
 */
function stripEmoji(text: string): string {
	const withoutEmoji = removeEmojiCharacters(text);
	if (withoutEmoji === text) {
		return text;
	}

	return withoutEmoji.replace(/ {2,}/g, " ");
}

