	if (toolName === "write") {
		const content = input.content;
		return typeof content === "string" ? [content] : [];
	}

	if (toolName !== "edit") {
		return [];
	}

	const edits = input.edits;
	if (!Array.isArray(edits)) {
		return [];
	}

