	for (const edit of edits) {
		if (typeof edit !== "object" || edit === null) {
			continue;
		}

		const newText = (edit as Record<string, unknown>).newText;
		if (typeof newText === "string") {
			replacements.push(newText);
		}
	}
	return replacements;
}

export default function noEmojiExtension(pi: ExtensionAPI) {
	let emojiBlocked = 0;
	let totalMessages = 0;

	pi.on("tool_call", async (event) => {
		const generatedContent = getGeneratedContent(event.toolName, event.input);
		if (generatedContent.length === 0) {
			return undefined;
		}

		const hasEmoji = generatedContent.some((content) => containsEmoji(content));
		if (!hasEmoji) {
			return undefined;
		}

		return {
			block: true,
			reason: "Emoji are not allowed in generated content. Use plain text and retry.",
		};
	});

	// Keep steering concise because deterministic checks handle misses.
	pi.on("before_agent_start", async (event) => {
		return {
			systemPrompt: appendNoEmojiInstruction(event.systemPrompt),
		};
	});

	// Block emoji in streaming messages
	pi.on("message_update", async (event) => {
		const message = event.message;
		if (message.role !== "assistant") return;

		const assistantMsg = message as AssistantMessage;
		for (const block of assistantMsg.content) {
			if (block.type === "text") {
