					code === 0x270c || code === 0x270d || code === 0x2728 || code === 0x2744 ||
					code === 0x2753 || code === 0x2754 || code === 0x2755 || code === 0x2757 ||
					code === 0x2b50 || code === 0x1f1e6);
			return !isEmoji;
		})
		.join("");
}

/**
 * True when the text carries at least one emoji.
 */
function containsEmoji(text: string): boolean {
	return removeEmojiCharacters(text) !== text;
}

/**
 * Remove all emoji from a string.
 *
 * Runs of spaces are tidied only when an emoji was actually removed, because
 * that is the only case where removal can leave a gap behind.
 */
function stripEmoji(text: string): string {
	const withoutEmoji = removeEmojiCharacters(text);
	if (withoutEmoji === text) {
		return text;
	}

	return withoutEmoji.replace(/ {2,}/g, " ");
}

function getGeneratedContent(toolName: string, input: Record<string, unknown>): string[] {
	if (toolName === "write") {
		const content = input.content;
		return typeof content === "string" ? [content] : [];
	}

	if (toolName !== "edit") {
		return [];
	}

	const edits = input.edits;
	if (!Array.isArray(edits)) {
		return [];
	}

	const replacements: string[] = [];
	for (const edit of edits) {
		if (typeof edit !== "object" || edit === null) {
			continue;
		}

		const newText = (edit as Record<string, unknown>).newText;
		if (typeof newText === "string") {
			replacements.push(newText);
		}
	}
	return replacements;
}

export default function noEmojiExtension(pi: ExtensionAPI) {
	let emojiBlocked = 0;
	let totalMessages = 0;

	pi.on("tool_call", async (event) => {
		const generatedContent = getGeneratedContent(event.toolName, event.input);
		if (generatedContent.length === 0) {
			return undefined;
		}

		const hasEmoji = generatedContent.some((content) => containsEmoji(content));
		if (!hasEmoji) {
			return undefined;
		}

		return {
			block: true,
			reason: "Emoji are not allowed in generated content. Use plain text and retry.",
		};
	});

	// Keep steering concise because deterministic checks handle misses.
	pi.on("before_agent_start", async (event) => {
		return {
			systemPrompt: appendNoEmojiInstruction(event.systemPrompt),
		};
	});

	// Block emoji in streaming messages
	pi.on("message_update", async (event) => {
		const message = event.message;
		if (message.role !== "assistant") return;

		const assistantMsg = message as AssistantMessage;
		for (const block of assistantMsg.content) {
			if (block.type === "text") {
				const originalText = block.text;
				const strippedText = stripEmoji(originalText);
				if (strippedText !== originalText) {
					emojiBlocked++;
					block.text = strippedText;
				}
			}
		}
	});

	// Final cleanup when message is complete
	pi.on("message_end", async (event, ctx) => {
		const message = event.message;
		if (message.role !== "assistant") return;

		totalMessages++;
		const assistantMsg = message as AssistantMessage;
		for (const block of assistantMsg.content) {
			if (block.type === "text") {
				const originalText = block.text;
				const strippedText = stripEmoji(originalText);
				if (strippedText !== originalText) {
					block.text = strippedText;
					emojiBlocked++;
				}
			}
		}

		// Periodically show status
		if (totalMessages % 10 === 0 && emojiBlocked > 0) {
			ctx.ui.setStatus("no-emoji", `Emoji blocked: ${emojiBlocked}`);
		}
	});

	// Show on session start
	pi.on("session_start", async (_event, _ctx) => {
		emojiBlocked = 0;
		totalMessages = 0;
	});
}

